import { API_BASE_URL } from '../config/api';

export interface Document {
  id: string;
  title: string;
  type: 'invoice' | 'contract' | 'receipt' | 'report';
  tags: string[];
  updatedAt: string;
}

export async function fetchDocuments(params: { query?: string; tag?: string; page: number }): Promise<Document[]> {
  const search = new URLSearchParams();
  if (params.query) search.set('q', params.query);
  if (params.tag) search.set('tag', params.tag);
  search.set('page', String(params.page));
  const response = await fetch(`${API_BASE_URL}/documents?${search.toString()}`);
  if (!response.ok) throw new Error(`Documents failed with status ${response.status}`);
  return (await response.json()) as Document[];
}

import { useCallback, useEffect, useRef, useState } from 'react';
import { View, Text, TextInput, TouchableOpacity, FlatList, StyleSheet, SafeAreaView, ActivityIndicator } from 'react-native';
import { fetchDocuments, type Document } from '../services/documents';

const colors = {
  muted: '#8a8f8a',
  accent: '#f05039',
  bg: '#0f120e',
  surface: '#1a1f1a',
  text: '#f5f5f0',
  borderAlt: '#2a2f2a',
  textMuted: '#a8ada6',
  border: '#242a24',
  danger: '#ff6b5e',
}

const TAGS = ['all', 'tax', 'legal', 'purchases'];

const TYPE_ICON: Record<Document['type'], string> = {
  invoice: '⅀',
  contract: '✎',
  receipt: '☰',
  report: '▤',
};

export function DocumentListScreen(): JSX.Element {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [query, setQuery] = useState('');
  const [tag, setTag] = useState('all');
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [hasMore, setHasMore] = useState(true);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const load = useCallback(async (reset: boolean) => {
    const nextPage = reset ? 1 : page;
    if (reset) setLoading(true);
    else setLoadingMore(true);
    setError(null);
    try {
      const data = await fetchDocuments({ query: query.trim() || undefined, tag: tag === 'all' ? undefined : tag, page: nextPage });
      setDocuments(prev => (reset ? data : [...prev, ...data]));
      setPage(nextPage + 1);
      setHasMore(data.length > 0);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load documents.');
    } finally {
      setLoading(false);
      setLoadingMore(false);
    }
  }, [query, tag, page]);

  useEffect(() => {
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => { void load(true); }, 300);
    return () => { if (timer.current) clearTimeout(timer.current); };
  }, [query, tag]);

  const renderItem = useCallback(({ item }: { item: Document }) => (
    <View style={styles.row}>
      <Text style={styles.icon} accessibilityLabel={`${item.type} document`}>{TYPE_ICON[item.type]}</Text>
      <View style={styles.info}>
        <Text style={styles.title} numberOfLines={1}>{item.title}</Text>
        <Text style={styles.meta}>{item.tags.join(' · ')}</Text>
      </View>
      <Text style={styles.date}>{new Date(item.updatedAt).toLocaleDateString()}</Text>
    </View>
  ), []);

  return (
    <SafeAreaView style={styles.safe}>
      <TextInput
        value={query}
        onChangeText={setQuery}
        placeholder="Search documents…"
        placeholderTextColor="{colors.muted}"
        accessibilityLabel="Search documents"
        style={styles.search}
      />
      <View style={styles.chips}>
        {TAGS.map(t => (
          <TouchableOpacity key={t} style={[styles.chip, tag === t && styles.chipActive]} onPress={() => setTag(t)} accessibilityRole="button">
            <Text style={[styles.chipText, tag === t && styles.chipTextActive]}>{t}</Text>
          </TouchableOpacity>
        ))}
      </View>
      {loading && <ActivityIndicator color="{colors.accent}" style={styles.center} />}
      {!loading && error && <Text style={styles.error}>{error}</Text>}
      {!loading && !error && documents.length === 0 && <Text style={styles.empty}>No documents found.</Text>}
      {!loading && !error && documents.length > 0 && (
        <FlatList
          data={documents}
          renderItem={renderItem}
          keyExtractor={d => d.id}
          onEndReached={() => { if (hasMore) void load(false); }}
          onEndReachedThreshold={0.4}
          ListFooterComponent={loadingMore ? <ActivityIndicator color="{colors.accent}" /> : null}
        />
      )}
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg },
  search: { backgroundColor: colors.surface, color: colors.text, borderRadius: 6, margin: 16, padding: 12, borderWidth: 1, borderColor: colors.borderAlt },
  chips: { flexDirection: 'row', gap: 8, paddingHorizontal: 16, marginBottom: 8 },
  chip: { backgroundColor: colors.surface, borderRadius: 16, paddingHorizontal: 12, paddingVertical: 6 },
  chipActive: { backgroundColor: colors.accent },
  chipText: { color: colors.textMuted },
  chipTextActive: { color: colors.bg },
  row: { flexDirection: 'row', alignItems: 'center', gap: 12, paddingHorizontal: 16, paddingVertical: 12, borderBottomWidth: 1, borderBottomColor: colors.border },
  icon: { color: colors.accent, fontSize: 18, width: 24 },
  info: { flex: 1 },
  title: { color: colors.text, fontWeight: '600' },
  meta: { color: colors.muted, fontSize: 11, marginTop: 2 },
  date: { color: colors.muted, fontSize: 11 },
  center: { marginTop: 40 },
  error: { color: colors.danger, textAlign: 'center', marginTop: 24 },
  empty: { color: colors.muted, textAlign: 'center', marginTop: 24 },
});
